#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <stdio.h>
#include <math.h>
#include <pthread.h>

#define ALIGNMENT 64
#define BLOCK_SIZE 104857600

typedef struct Block {
    void* ptr;
    size_t size;
    size_t used;
    struct Block* next;
} Block;

typedef struct Arena {
    Block* head;
    pthread_mutex_t lock;
} Arena;

static Arena global_arena;

void init_memory_subsystem() {
    global_arena.head = NULL;
    pthread_mutex_init(&global_arena.lock, NULL);
}

void* aligned_alloc_internal(size_t size) {
    void* ptr = NULL;
    int ret = posix_memalign(&ptr, ALIGNMENT, size);
    if (ret != 0) return NULL;
    return ptr;
}

void* arena_alloc(size_t size) {
    pthread_mutex_lock(&global_arena.lock);

    size_t aligned_size = (size + ALIGNMENT - 1) & ~(ALIGNMENT - 1);

    Block* current = global_arena.head;
    while (current != NULL) {
        if (current->used + aligned_size <= current->size) {
            void* ptr = (char*)current->ptr + current->used;
            current->used += aligned_size;
            pthread_mutex_unlock(&global_arena.lock);
            return ptr;
        }
        current = current->next;
    }

    size_t new_block_size = BLOCK_SIZE;
    if (aligned_size > new_block_size) {
        new_block_size = aligned_size;
    }

    Block* new_block = (Block*)malloc(sizeof(Block));
    new_block->ptr = aligned_alloc_internal(new_block_size);
    new_block->size = new_block_size;
    new_block->used = aligned_size;
    new_block->next = global_arena.head;
    global_arena.head = new_block;

    pthread_mutex_unlock(&global_arena.lock);
    return new_block->ptr;
}

void arena_reset() {
    pthread_mutex_lock(&global_arena.lock);
    Block* current = global_arena.head;
    while (current != NULL) {
        current->used = 0;
        current = current->next;
    }
    pthread_mutex_unlock(&global_arena.lock);
}

void mem_copy(float* dest, float* src, size_t count) {
    memcpy(dest, src, count * sizeof(float));
}

void mem_zero(float* dest, size_t count) {
    memset(dest, 0, count * sizeof(float));
}

void mem_set(float* dest, float val, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        dest[i] = val;
    }
}

float fast_inv_sqrt(float number) {
    long i;
    float x2, y;
    const float threehalfs = 1.5F;
    x2 = number * 0.5F;
    y = number;
    i = * ( long * ) &y;
    i = 0x5f3759df - ( i >> 1 );
    y = * ( float * ) &i;
    y = y * ( threehalfs - ( x2 * y * y ) );
    return y;
}

void matrix_print(float* data, int rows, int cols) {
    for(int i=0; i<rows; i++) {
        for(int j=0; j<cols; j++) {
            printf("%f ", data[i*cols + j]);
        }
        printf("\n");
    }
}

export void vec_add(uniform float a[], uniform float b[], uniform float out[], uniform int count) {
    foreach (i = 0 ... count) {
        out[i] = a[i] + b[i];
    }
}

export void vec_sub(uniform float a[], uniform float b[], uniform float out[], uniform int count) {
    foreach (i = 0 ... count) {
        out[i] = a[i] - b[i];
    }
}

export void vec_mul(uniform float a[], uniform float b[], uniform float out[], uniform int count) {
    foreach (i = 0 ... count) {
        out[i] = a[i] * b[i];
    }
}

export void vec_scale(uniform float a[], uniform float scalar, uniform float out[], uniform int count) {
    foreach (i = 0 ... count) {
        out[i] = a[i] * scalar;
    }
}

export void mat_mul(uniform float A[], uniform float B[], uniform float C[], 
                    uniform int M, uniform int N, uniform int K) {
    foreach (row = 0 ... M, col = 0 ... K) {
        float sum = 0.0f;
        for (uniform int i = 0; i < N; ++i) {
            sum += A[row * N + i] * B[i * K + col];
        }
        C[row * K + col] = sum;
    }
}

export void activation_sigmoid(uniform float in[], uniform float out[], uniform int count) {
    foreach (i = 0 ... count) {
        float x = in[i];
        out[i] = 1.0f / (1.0f + exp(-x));
    }
}

export void activation_tanh(uniform float in[], uniform float out[], uniform int count) {
    foreach (i = 0 ... count) {
        float x = in[i];
        float e_pos = exp(x);
        float e_neg = exp(-x);
        out[i] = (e_pos - e_neg) / (e_pos + e_neg);
    }
}

export void activation_relu(uniform float in[], uniform float out[], uniform int count) {
    foreach (i = 0 ... count) {
        float x = in[i];
        if (x > 0.0f) {
            out[i] = x;
        } else {
            out[i] = 0.0f;
        }
    }
}

export void activation_softmax(uniform float in[], uniform float out[], uniform int rows, uniform int cols) {
    foreach (r = 0 ... rows) {
        float max_val = -1000000.0f;
        for (uniform int c = 0; c < cols; ++c) {
            float val = in[r * cols + c];
            if (val > max_val) {
                max_val = val;
            }
        }

        float sum = 0.0f;
        for (uniform int c = 0; c < cols; ++c) {
            float val = in[r * cols + c];
            float exp_v = exp(val - max_val);
            out[r * cols + c] = exp_v;
            sum += exp_v;
        }

        for (uniform int c = 0; c < cols; ++c) {
            out[r * cols + c] /= sum;
        }
    }
}

export void elementwise_diff_sq(uniform float a[], uniform float b[], uniform float out[], uniform int count) {
    foreach (i = 0 ... count) {
        float d = a[i] - b[i];
        out[i] = d * d;
    }
}

export void update_weights_sgd(uniform float weights[], uniform float grads[], uniform float lr, uniform int count) {
    foreach (i = 0 ... count) {
        weights[i] = weights[i] - (lr * grads[i]);
    }
}

export void dropout_mask(uniform float in[], uniform float out[], uniform float mask[], uniform int count) {
    foreach (i = 0 ... count) {
        out[i] = in[i] * mask[i];
    }
}

export void layer_norm(uniform float in[], uniform float out[], uniform float gamma[], uniform float beta[], uniform int rows, uniform int cols) {
    foreach (r = 0 ... rows) {
        float mean = 0.0f;
        for (uniform int c = 0; c < cols; ++c) {
            mean += in[r * cols + c];
        }
        mean /= cols;

        float var = 0.0f;
        for (uniform int c = 0; c < cols; ++c) {
            float diff = in[r * cols + c] - mean;
            var += diff * diff;
        }
        var /= cols;
        float std_dev = sqrt(var + 0.00001f);

        for (uniform int c = 0; c < cols; ++c) {
            float norm = (in[r * cols + c] - mean) / std_dev;
            out[r * cols + c] = norm * gamma[c] + beta[c];
        }
    }
}

