(deftype Tensor [
    ptr (Ptr Float)
    rows Int
    cols Int
    size Int
])

(defmodule Tensor
    (defn create [r c]
        (let [sz (* r c)
              p (arena-alloc (Long.from-int (* sz 4)))]
            (do
                (mem-zero p (Long.from-int sz))
                (Tensor.init p r c sz))))

    (defn from-val [r c v]
        (let [t (create r c)]
            (do
                (mem-set (Tensor.ptr t) v (Long.from-int (Tensor.size t)))
                t)))

    (defn raw [t]
        (Tensor.ptr t))
)

(deftype Layer [
    weights Tensor
    biases Tensor
    output Tensor
    grad-w Tensor
    grad-b Tensor
])

(defmodule Layer
    (defn create [in-dim out-dim]
        (Layer.init
            (Tensor.from-val in-dim out-dim 0.01f)
            (Tensor.create 1 out-dim)
            (Tensor.create 1 out-dim)
            (Tensor.create in-dim out-dim)
            (Tensor.create 1 out-dim)))

    (defn forward [layer input]
        (let [w (Layer.weights layer)
              b (Layer.biases layer)
              out (Layer.output layer)
              w-ptr (Tensor.raw w)
              b-ptr (Tensor.raw b)
              in-ptr (Tensor.raw input)
              out-ptr (Tensor.raw out)
              m (Tensor.rows input)
              n (Tensor.cols w)
              k (Tensor.cols input)]
            (do
                (mat-mul in-ptr w-ptr out-ptr m n k)
                (activation-relu out-ptr out-ptr (* m n))
                out)))

    (defn update [layer lr]
        (let [w (Layer.weights layer)
              gw (Layer.grad-w layer)
              sz (Tensor.size w)]
            (update-weights-sgd (Tensor.raw w) (Tensor.raw gw) lr sz)))
)

(deftype Network [
    l1 Layer
    l2 Layer
    l3 Layer
])

(defmodule Network
    (defn init-model [in-d hidden-d out-d]
        (Network.init
            (Layer.create in-d hidden-d)
            (Layer.create hidden-d hidden-d)
            (Layer.create hidden-d out-d)))

    (defn predict [net input]
        (let [h1 (Layer.forward (Network.l1 net) input)
              h2 (Layer.forward (Network.l2 net) h1)
              out (Layer.forward (Network.l3 net) h2)]
            out))
)

(load "types.carp")

(defn main []
    (do
        (init-memory-subsystem)
        (println* "AGI_CORE: MEMORY_SUBSYSTEM_INITIALIZED")

        (let [model (Network.init-model 768 2048 768)
              input-batch (Tensor.from-val 32 768 0.5f)
              cycles 1000]

            (for [i 0 cycles]
                (let [output (Network.predict model input-batch)
                      raw-ptr (Tensor.raw output)]
                    (do
                        (if (= (mod i 100) 0)
                            (println* "AGI_CORE: CYCLE_" i "_COMPUTE_COMPLETE_TENSOR_HASH_" (Pointer.to-long raw-ptr))
                            ())
                        (arena-reset) 
                        )))

            (println* "AGI_CORE: SHUTDOWN_SEQUENCE_INITIATED")
    )))

